mapper.select:
SELECT
    /* 잠재고객 미상담 고객 수 */
    (
        SELECT COUNT(*)
        FROM potential_customer pc
        WHERE pc.sales_user_id = #{salesUserId}
            AND pc.consult_status_code = '01'
            AND pc.is_active = FALSE               /* 졸업 고객 제외 */
    ) AS uncontactedCustomerCount,

    /* 잠재고객 상담중 고객 수 */
    (
        SELECT COUNT(*)
        FROM potential_customer pc
        WHERE pc.sales_user_id = #{salesUserId}
            AND pc.consult_status_code = '02'
            AND pc.is_active = FALSE              /* 졸업 고객 제외 */
    ) AS consultingCustomerCount,

    /* 설계중 고객 수 */
    (
        SELECT COUNT(*)
        FROM contract c
        WHERE c.sales_user_id = #{salesUserId}
            AND c.contract_status_code = '01'
    ) AS designingContractCount,

    /* 설계완료 고객 수 */
    (
        SELECT COUNT(*)
        FROM contract c
        WHERE c.sales_user_id = #{salesUserId}
            AND c.contract_status_code = '02'
    ) AS designedContractCount,

    /* 청약중 고객 수 */
    (
        SELECT COUNT(*)
        FROM contract c
        WHERE c.sales_user_id = #{salesUserId}
            AND c.contract_status_code = '03'
    ) AS subscriptionInProgressCount,

    /* 청약완료 고객 수 */
    (
        SELECT COUNT(*)
        FROM contract c
        WHERE c.sales_user_id = #{salesUserId}
            AND c.contract_status_code = '04'
    ) AS subscriptionCompletedCount,

    /* 수납완료 고객 수 */
    (
        SELECT COUNT(*)
        FROM contract c
        WHERE c.sales_user_id = #{salesUserId}
            AND c.contract_status_code = '06'
    ) AS paymentCompletedCount,

    /*계약완료 고객 수 */
    (
        SELECT COUNT(*)
        FROM contract c
        WHERE c.sales_user_id = #{salesUserId}
            AND c.contract_result_status_code = '02'
    ) AS contractCompletedCount

SELECT
    COALESCE(
            (
                SELECT smt.target_contract_count
                FROM sales_monthly_target smt
                WHERE smt.sales_user_id = #{salesUserId}
                  AND smt.target_year_month = DATE_FORMAT(CURDATE(), '%Y%m')
            LIMIT 1
        ),
    150
) AS targetContractCount,

    (
        SELECT COUNT(*)
        FROM contract c
        WHERE c.sales_user_id = #{salesUserId}
          AND c.contract_result_status_code = '02'
          AND DATE_FORMAT(c.updated_at, '%Y%m') = DATE_FORMAT(CURDATE(), '%Y%m')
    ) AS completedContractCount,

    ROUND(
            (
                (
                    SELECT COUNT(*)
                    FROM contract c
                    WHERE c.sales_user_id = #{salesUserId}
                      AND c.contract_result_status_code = '02'
                      AND DATE_FORMAT(c.updated_at, '%Y%m') = DATE_FORMAT(CURDATE(), '%Y%m')
                ) * 100.0
                )
                /
            COALESCE(
                    (
                        SELECT smt.target_contract_count
                        FROM sales_monthly_target smt
                        WHERE smt.sales_user_id = #{salesUserId}
                          AND smt.target_year_month = DATE_FORMAT(CURDATE(), '%Y%m')
                    LIMIT 1
                ),
        150
    )
) AS achievementRate
